using System.IO.Compression;using LightroomIsSlow.Core.Support;
namespace LightroomIsSlow.Core.Tests;
public sealed class SupportBundleTests{[Fact]public void BundleOnlyIncludesAllowlistedDiagnosticFiles(){var d=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(d);try{File.WriteAllText(Path.Combine(d,"session.json"),"{}");File.WriteAllText(Path.Combine(d,"telemetry.jsonl"),"{}");File.WriteAllText(Path.Combine(d,"secret.jpg"),"photo");var z=new SupportBundleBuilder().Create(d);using(var a=ZipFile.OpenRead(z)){Assert.Contains(a.Entries,x=>x.FullName=="session.json");Assert.DoesNotContain(a.Entries,x=>x.FullName=="secret.jpg");}File.Delete(z);}finally{Directory.Delete(d,true);}}}
